<?php $p=__DIR__.'/tmp/sessions';if(!is_dir($p))mkdir($p,0770,true);session_save_path($p);session_start();require_once __DIR__.'/lib/workspace.php';$_SESSION['csrf']??=bin2hex(random_bytes(16));$items=workspaceData('candidates.json',[]);$stages=['Applied','Screening','Interview','Offer','Rejected'];$activePage='pipeline';$pageTitle='Pipeline · ResumeIQ';$pageStyles='<style>.board-tools{display:grid;grid-template-columns:1fr 170px 170px;gap:8px;margin:12px 0}.board{display:grid;grid-template-columns:repeat(5,minmax(220px,1fr));gap:10px;overflow-x:auto;padding-bottom:8px}.column{min-height:510px;background:#f0f1f7;border:1px solid var(--line);border-radius:16px;padding:9px}.column.over{outline:2px solid var(--primary)}.column-head{display:flex;justify-content:space-between;padding:5px 4px 11px;font-weight:700;font-size:11px}.column-head b{padding:2px 7px;border-radius:7px;background:#e3e3ed;color:var(--muted)}.drop{min-height:450px}.candidate-card{background:#fff;border:1px solid var(--line);border-radius:13px;padding:13px;margin-bottom:8px;cursor:grab;box-shadow:0 7px 18px rgba(34,32,60,.035)}.candidate-card.drag{opacity:.42}.card-top{display:flex;justify-content:space-between;gap:8px}.card-top strong{font-size:11px}.card-role{font-size:9px;color:var(--muted);margin:4px 0 10px}.tags{display:flex;gap:4px;flex-wrap:wrap}.card-foot{display:flex;justify-content:space-between;border-top:1px dashed var(--line);margin-top:11px;padding-top:9px;color:var(--muted);font-size:8px}.drop-empty{text-align:center;color:#a0a3af;padding:20px;font-size:9px}@media(max-width:850px){.board{grid-template-columns:repeat(5,250px)}.board-tools{grid-template-columns:1fr}}</style>';require __DIR__.'/views/partials/header.php';?>
<section class="page-head"><div><div class="kicker"><i class="fa-solid fa-table-columns"></i> Hiring workflow</div><h1>Candidate pipeline</h1><p>Drag cards between stages. Every move is saved automatically.</p></div><a class="btn btn-primary" href="index.php"><i class="fa-solid fa-plus"></i>Add candidate</a></section><div class="board-tools"><input class="control" id="pipelineSearch" placeholder="Search candidate or skill"><select class="control" id="source"><option value="">All sources</option><?php foreach(array_unique(array_column($items,'source')) as $s):?><option><?=htmlspecialchars($s)?></option><?php endforeach?></select><select class="control" id="score"><option value="0">Any score</option><option value="50">50%+</option><option value="70">70%+</option><option value="85">85%+</option></select></div><section class="board"><?php foreach($stages as $stage):$group=array_filter($items,fn($x)=>($x['stage']??'Applied')===$stage);?><article class="column" data-stage="<?=$stage?>"><div class="column-head"><?=$stage?><b class="count"><?=count($group)?></b></div><div class="drop"><?php foreach($group as $c):$present=candidatePresentation($c);?><div draggable="true" class="candidate-card" data-id="<?=htmlspecialchars($c['id'])?>" data-find="<?=htmlspecialchars(strtolower($present['name'].' '.$present['role'].' '.implode(' ',$c['skills']??[])))?>" data-source="<?=htmlspecialchars($c['source']??'')?>" data-score="<?=(int)$c['score']?>"><div class="card-top"><strong><?=htmlspecialchars($present['name'])?></strong><span class="score-text"><?=(int)$c['score']?>%</span></div><div class="card-role"><?=htmlspecialchars($present['role'])?></div><div class="tags"><?php foreach(array_slice($c['skills']??[],0,3) as $s):?><span class="tag"><?=htmlspecialchars($s)?></span><?php endforeach?></div><div class="card-foot"><span><?=htmlspecialchars($c['source']??'Direct upload')?></span><span><?=!empty($c['experience']['total_months'])?round($c['experience']['total_months']/12,1).' years':'Experience unknown'?></span></div></div><?php endforeach?><div class="drop-empty" <?=$group?'style="display:none"':''?>>Drop candidate here</div></div></article><?php endforeach?></section><script>const token='<?=$_SESSION['csrf']?>',cards=[...document.querySelectorAll('.candidate-card')],cols=[...document.querySelectorAll('.column')];let drag;cards.forEach(c=>{c.ondragstart=()=>{drag=c;c.classList.add('drag')};c.ondragend=()=>c.classList.remove('drag')});function recount(){cols.forEach(c=>{const v=[...c.querySelectorAll('.candidate-card')].filter(x=>x.style.display!=='none');c.querySelector('.count').textContent=v.length;c.querySelector('.drop-empty').style.display=v.length?'none':'block'})}cols.forEach(c=>{c.ondragover=e=>{e.preventDefault();c.classList.add('over')};c.ondragleave=()=>c.classList.remove('over');c.ondrop=async e=>{e.preventDefault();c.classList.remove('over');const old=drag.parentElement;c.querySelector('.drop').appendChild(drag);recount();const r=await fetch('pipeline_api.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({id:drag.dataset.id,stage:c.dataset.stage,csrf:token})});if(!r.ok){old.appendChild(drag);recount();alert('Move could not be saved')}}});function filter(){const q=document.getElementById('pipelineSearch').value.toLowerCase(),s=document.getElementById('source').value,m=+document.getElementById('score').value;cards.forEach(c=>c.style.display=(!q||c.dataset.find.includes(q))&&(!s||c.dataset.source===s)&&+c.dataset.score>=m?'block':'none');recount()}document.querySelectorAll('.board-tools input,.board-tools select').forEach(x=>x.oninput=filter);document.getElementById('globalSearch').oninput=e=>{document.getElementById('pipelineSearch').value=e.target.value;filter()}</script>
